    @JvmStatic
    fun localizedDigits(context: Context, value: String): String {
        if (value.isEmpty()) return value
        val digitSets = arrayOf(
            "0123456789", "०१२३४५६७८९", "०१२३४५६७८९", "૦૧૨૩૪૫૬૭૮૯",
            "০১২৩৪৫৬৭৮৯", "௦௧௨௩௪௫௬௭௮௯", "౦౧౨౩౪౫౬౭౮౯", "೦೧೨೩೪೫೬೭೮೯",
            "൦൧൨൩൪൫൬൭൮൯"
        )
        val targetDigits = digitSets[getSavedLanguageIndex(context).coerceAtMost(digitSets.lastIndex)]
        return buildString(value.length) {
            value.forEach { character ->
                val digitIndex = digitSets[0].indexOf(character)
                append(if (digitIndex >= 0) targetDigits[digitIndex] else character)
            }
        }
    }

