    @JvmStatic
    fun localizeReportGuideText(context: Context, value: String): String {
        val lostLabel = profileText(context, "lost_theft_button")
        val foundLabel = profileText(context, "found_button")
        return value
            .replace("Completed reports", profileText(context, "completed_reports"))
            .replace("LOST/THEFT", lostLabel)
            .replace("LOST/FOUND", "$lostLabel/$foundLabel")
            .replace("Lost/Found", "$lostLabel/$foundLabel")
            .replace("LOST", lostLabel)
            .replace("THEFT", profileText(context, "theft_label"))
            .replace("FOUND", foundLabel)
            .replace("Community Guidelines", profileText(context, "community_guidelines"))
            .replace("My Reports", profileText(context, "my_reports"))
            .replace("My reports", profileText(context, "my_reports"))
            .replace("Search", profileText(context, "search_label"))
            .replace("Active", profileText(context, "active_status"))
            .replace("Completed", profileText(context, "completed_status"))
            .replace("Edit", adoptionText(context, "adopt_edit"))
            .replace("Delete", adoptionText(context, "adopt_delete"))
            .replace("deleting", adoptionText(context, "adopt_delete").lowercase())
            .replace("delete", adoptionText(context, "adopt_delete").lowercase())
            .replace("reunited", profileText(context, "reunited_status"))
            .replace("Home", profileText(context, "home_label"))
            .replace("Adopt a Pet", adoptionText(context, "adopt_title"))
    }

