            "adopt_choose_gallery" -> arrayOf("Choose from gallery", "गैलरी से चुनें", "गॅलरीतून निवडा", "ગેલેરીમાંથી પસંદ કરો", "গ্যালারি থেকে বেছে নিন", "கேலரியில் இருந்து தேர்வு செய்யவும்", "గ్యాలరీ నుంచి ఎంచుకోండి", "ಗ್ಯಾಲರಿಯಿಂದ ಆಯ್ಕೆಮಾಡಿ", "ഗാലറിയിൽ നിന്ന് തിരഞ്ഞെടുക്കുക")
            "adopt_take_photo" -> arrayOf("Take photo", "तस्वीर लें", "फोटो काढा", "ફોટો લો", "ছবি তুলুন", "படம் எடுக்கவும்", "ఫోటో తీయండి", "ಫೋಟೋ ತೆಗೆಯಿರಿ", "ചിത്രം എടുക്കുക")
            "adopt_capture" -> arrayOf("Capture", "तस्वीर लें", "फोटो काढा", "ફોટો લો", "ছবি তুলুন", "படம் எடுக்கவும்", "ఫోటో తీయండి", "ಫೋಟೋ ತೆಗೆಯಿರಿ", "ചിത്രം എടുക്കുക")
            "crop_photo" -> arrayOf("Crop photo", "तस्वीर काटें", "फोटो क्रॉप करा", "ફોટો કાપો", "ছবি ক্রপ করুন", "படத்தை வெட்டவும்", "ఫోటోను కత్తిరించండి", "ಫೋಟೋ ಕ್ರಾಪ್ ಮಾಡಿ", "ചിത്രം ക്രോപ്പ് ചെയ്യുക")
            "crop_photo_instructions" -> arrayOf("Drag inside to move the crop. Drag a corner to resize.", "क्रॉप को खिसकाने के लिए अंदर खींचें। आकार बदलने के लिए कोने को खींचें।", "क्रॉप हलवण्यासाठी आत ड्रॅग करा. आकार बदलण्यासाठी कोपरा ड्रॅग करा.", "ક્રોપ ખસેડવા અંદર ખેંચો. કદ બદલવા ખૂણો ખેંચો.", "ক্রপ সরাতে ভেতরে টানুন। আকার বদলাতে কোণা টানুন।", "படவெட்டுப் பகுதியை நகர்த்த உள்ளே இழுக்கவும். அளவை மாற்ற மூலையை இழுக்கவும்.", "క్రాప్‌ను జరపడానికి లోపలికి లాగండి. పరిమాణం మార్చడానికి మూలను లాగండి.", "ಕ್ರಾಪ್ ಸರಿಸಲು ಒಳಗೆ ಎಳೆಯಿರಿ. ಗಾತ್ರ ಬದಲಿಸಲು ಮೂಲೆಯನ್ನು ಎಳೆಯಿರಿ.", "ക്രോപ്പ് നീക്കാൻ ഉള്ളിൽ വലിക്കുക. വലുപ്പം മാറ്റാൻ മൂല വലിക്കുക.")
            "crop_photo_confirm" -> arrayOf("Use photo", "तस्वीर इस्तेमाल करें", "फोटो वापरा", "ફોટો વાપરો", "ছবি ব্যবহার করুন", "படத்தைப் பயன்படுத்தவும்", "ఫోటోను ఉపయోగించండి", "ಫೋಟೋ ಬಳಸಿ", "ചിത്രം ഉപയോഗിക്കുക")
            "adopt_camera_permission" -> arrayOf("Allow camera access to take a pet photo.", "पालतू की तस्वीर लेने के लिए कैमरा एक्सेस की अनुमति दें।", "प्राण्याचा फोटो घेण्यासाठी कॅमेरा परवानगी द्या.", "પ્રાણીનો ફોટો લેવા માટે કેમેરાની પરવાનગી આપો.", "পোষ্যের ছবি তুলতে ক্যামেরার অনুমতি দিন।", "செல்லப்பிராணிப் படம் எடுக்க கேமரா அனுமதியை வழங்கவும்.", "జంతువు ఫోటో తీయడానికి కెమెరా అనుమతించండి.", "ಸಾಕುಪ್ರಾಣಿಯ ಫೋಟೋ ತೆಗೆಯಲು ಕ್ಯಾಮೆರಾ ಅನುಮತಿಸಿ.", "വളർത്തുമൃഗത്തിന്റെ ചിത്രം എടുക്കാൻ ക്യാമറ അനുമതി നൽകുക.")
            "adopt_camera_unavailable" -> arrayOf("Could not start the camera or capture the photo. Please try again or choose from gallery.", "कैमरा शुरू नहीं हो सका या तस्वीर नहीं ली जा सकी। फिर से कोशिश करें या गैलरी से चुनें।", "कॅमेरा सुरू करता आला नाही किंवा फोटो घेता आला नाही. पुन्हा प्रयत्न करा किंवा गॅलरीतून निवडा.", "કેમેરા શરૂ થઈ શક્યો નથી અથવા ફોટો લઈ શકાયો નથી. ફરી પ્રયાસ કરો અથવા ગેલેરીમાંથી પસંદ કરો.", "ক্যামেরা চালু করা বা ছবি তোলা যায়নি। আবার চেষ্টা করুন অথবা গ্যালারি থেকে বেছে নিন।", "கேமராவைத் தொடங்கவோ படமெடுக்கவோ முடியவில்லை. மீண்டும் முயற்சிக்கவும் அல்லது கேலரியில் இருந்து தேர்வு செய்யவும்.", "కెమెరాను ప్రారంభించలేకపోయాము లేదా ఫోటో తీయలేకపోయాము. మళ్లీ ప్రయత్నించండి లేదా గ్యాలరీ నుంచి ఎంచుకోండి.", "ಕ್ಯಾಮೆರಾ ಪ್ರಾರಂಭಿಸಲು ಅಥವಾ ಫೋಟೋ ತೆಗೆಯಲು ಸಾಧ್ಯವಾಗಲಿಲ್ಲ. ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ ಅಥವಾ ಗ್ಯಾಲರಿಯಿಂದ ಆಯ್ಕೆಮಾಡಿ.", "ക്യാമറ ആരംഭിക്കാനോ ചിത്രം എടുക്കാനോ കഴിഞ്ഞില്ല. വീണ്ടും ശ്രമിക്കുക അല്ലെങ്കിൽ ഗാലറിയിൽ നിന്ന് തിരഞ്ഞെടുക്കുക.")
            "adopt_social_optin" -> arrayOf("Auto-post this pet adoption to our official Facebook & Instagram pages to help find a home faster.", "जल्दी घर ढूँढने में मदद के लिए इस पालतू की पोस्ट हमारे आधिकारिक Facebook और Instagram पेजों पर अपने-आप साझा करें।", "लवकर घर मिळण्यासाठी ही नोंद आमच्या अधिकृत Facebook आणि Instagram पेजवर आपोआप पोस्ट करा.", "ઝડપથી ઘર શોધવામાં મદદ માટે આ પ્રાણીની પોસ્ટ અમારા સત્તાવાર Facebook અને Instagram પેજ પર આપમેળે મૂકો.", "দ্রুত বাড়ি খুঁজতে এই পোষ্যের পোস্ট আমাদের অফিসিয়াল Facebook ও Instagram পেজে স্বয়ংক্রিয়ভাবে দিন।", "விரைவில் வீடு கிடைக்க இந்தப் பதிவை எங்கள் அதிகாரப்பூர்வ Facebook மற்றும் Instagram பக்கங்களில் தானாகப் பகிரவும்.", "త్వరగా ఇల్లు దొరకడానికి ఈ పోస్ట్‌ను మా అధికారిక Facebook, Instagram పేజీల్లో ఆటోమేటిక్‌గా పోస్ట్ చేయండి.", "ಬೇಗ ಮನೆ ಸಿಗಲು ಈ ಪೋಸ್ಟ್ ಅನ್ನು ನಮ್ಮ ಅಧಿಕೃತ Facebook ಮತ್ತು Instagram ಪುಟಗಳಲ್ಲಿ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಹಂಚಿಕೊಳ್ಳಿ.", "വേഗത്തിൽ വീട് കണ്ടെത്താൻ ഈ പോസ്റ്റ് ഞങ്ങളുടെ ഔദ്യോഗിക Facebook, Instagram പേജുകളിൽ സ്വയമേവ പങ്കിടുക.")
            "adopt_social_optional" -> arrayOf("Optional. If posting fails, your Fendly listing will remain available.", "वैकल्पिक। पोस्ट न हो पाने पर भी आपकी Fendly सूची उपलब्ध रहेगी।", "ऐच्छिक. पोस्ट अयशस्वी झाले तरी Fendly नोंद उपलब्ध राहील.", "વૈકલ્પિક. પોસ્ટ નિષ્ફળ જાય તો પણ Fendly યાદી ઉપલબ્ધ રહેશે.", "ঐচ্ছিক। পোস্ট ব্যর্থ হলেও আপনার Fendly তালিকা থাকবে।", "விருப்பத்தேர்வு. பதிவு தோல்வியடைந்தாலும் Fendly பட்டியல் இருக்கும்.", "ఐచ్ఛికం. పోస్ట్ విఫలమైనా Fendly జాబితా అందుబాటులో ఉంటుంది.", "ಐಚ್ಛಿಕ. ಪೋಸ್ಟ್ ವಿಫಲವಾದರೂ Fendly ಪಟ್ಟಿ ಲಭ್ಯವಿರುತ್ತದೆ.", "ഐച്ഛികം. പോസ്റ്റ് പരാജയപ്പെട്ടാലും Fendly പട്ടിക തുടരും.")
            "adopt_cancel" -> arrayOf("Cancel", "रद्द करें", "रद्द करा", "રદ કરો", "বাতিল", "ரத்துசெய்", "రద్దు చేయండి", "ರದ್ದುಮಾಡಿ", "റദ്ദാക്കുക")
            "adopt_publish" -> arrayOf("Publish listing", "सूची प्रकाशित करें", "नोंद प्रकाशित करा", "યાદી પ્રકાશિત કરો", "তালিকা প্রকাশ করুন", "பட்டியலை வெளியிடு", "జాబితాను ప్రచురించండి", "ಪಟ್ಟಿ ಪ್ರಕಟಿಸಿ", "പട്ടിക പ്രസിദ്ധീകരിക്കുക")
            "adopt_required_fields" -> arrayOf("Complete the required fields and choose a pet photo.", "ज़रूरी जानकारी भरें और पालतू की तस्वीर चुनें।", "आवश्यक माहिती भरा आणि प्राण्याचा फोटो निवडा.", "જરૂરી વિગતો भरो અને પ્રાણીનો ફોટો પસંદ કરો.", "প্রয়োজনীয় তথ্য পূরণ করুন ও পোষ্যের ছবি বেছে নিন।", "தேவையான விவரங்களை நிரப்பி செல்லப்பிராணிப் படத்தைத் தேர்ந்தெடுக்கவும்.", "అవసరమైన వివరాలు నింపి జంతువు ఫోటోను ఎంచుకోండి.", "ಅಗತ್ಯ ವಿವರಗಳನ್ನು ತುಂಬಿ ಸಾಕುಪ್ರಾಣಿಯ ಫೋಟೋ ಆಯ್ಕೆಮಾಡಿ.", "ആവശ്യമായ വിവരങ്ങൾ പൂരിപ്പിച്ച് ചിത്രം തിരഞ്ഞെടുക്കുക.")
            "adopt_invalid_fields" -> arrayOf("Check the field limits: age 0–600 months, pet name up to 120 characters, species 60, breed 120, health 500, description 5,000, and city 120.", "जानकारी की सीमाएँ जाँचें: उम्र 0–600 महीने; नाम 120, प्रजाति 60, नस्ल 120, स्वास्थ्य 500, विवरण 5,000 और शहर 120 अक्षरों तक।", "माहितीच्या मर्यादा तपासा: वय ०–६०० महिने; नाव १२०, प्रजाती ६०, जात १२०, आरोग्य ५००, वर्णन ५,००० आणि शहर १२० अक्षरांपर्यंत.", "માહિતીની મર્યાદા તપાસો: ઉંમર ૦–૬૦૦ મહિના; નામ ૧૨૦, પ્રજાતિ ૬૦, જાતિ ૧૨૦, આરોગ્ય ૫૦૦, વર્ણન ૫,૦૦૦ અને શહેર ૧૨૦ અક્ષર સુધી.", "তথ্যের সীমা দেখুন: বয়স ০–৬০০ মাস; নাম ১২০, প্রজাতি ৬০, জাত ১২০, স্বাস্থ্য ৫০০, বিবরণ ৫,০০০ এবং শহর ১২০ অক্ষর পর্যন্ত।", "விவர வரம்புகளைச் சரிபார்க்கவும்: வயது 0–600 மாதங்கள்; பெயர் 120, இனம் 60, வகை 120, உடல்நலம் 500, விளக்கம் 5,000, நகரம் 120 எழுத்துகள் வரை.", "వివరాల పరిమితులను తనిఖీ చేయండి: వయస్సు 0–600 నెలలు; పేరు 120, జాతి 60, రకం 120, ఆరోగ్యం 500, వివరణ 5,000, నగరం 120 అక్షరాల వరకు.", "ವಿವರಗಳ ಮಿತಿಯನ್ನು ಪರಿಶೀಲಿಸಿ: ವಯಸ್ಸು 0–600 ತಿಂಗಳು; ಹೆಸರು 120, ಪ್ರಭೇದ 60, ತಳಿ 120, ಆರೋಗ್ಯ 500, ವಿವರಣೆ 5,000 ಮತ್ತು ನಗರ 120 ಅಕ್ಷರಗಳವರೆಗೆ.", "വിവരങ്ങളുടെ പരിധി പരിശോധിക്കുക: പ്രായം 0–600 മാസം; പേര് 120, ഇനം 60, വർഗം 120, ആരോഗ്യം 500, വിവരണം 5,000, നഗരം 120 അക്ഷരങ്ങൾ വരെ.")
