    @JvmStatic
    fun communityGuidelinesHtml(context: Context, darkMode: Boolean): String {
        val translations = arrayOf(
            arrayOf("Fendly Community Guidelines", "Fendly समुदाय दिशानिर्देश", "Fendly समुदाय मार्गदर्शक तत्त्वे", "Fendly સમુદાય માર્ગદર્શિકા", "Fendly সম্প্রদায়ের নির্দেশিকা", "Fendly சமூக வழிகாட்டுதல்கள்", "Fendly సంఘం మార్గదర్శకాలు", "Fendly ಸಮುದಾಯ ಮಾರ್ಗಸೂಚಿಗಳು", "Fendly കമ്മ്യൂണിറ്റി മാർഗ്ഗനിർദ്ദേശങ്ങൾ"),
            arrayOf("Fendly helps people reconnect with lost belongings, pets, and loved ones. Keep reports accurate, respectful, and focused on recovery.", "Fendly खोई हुई वस्तुओं, पालतू जानवरों और अपनों को फिर से मिलाने में मदद करता है। रिपोर्ट सटीक, सम्मानजनक और खोज पर केंद्रित रखें।", "Fendly हरवलेल्या वस्तू, पाळीव प्राणी आणि प्रिय व्यक्तींना पुन्हा मिळवण्यात मदत करते. अहवाल अचूक, आदरयुक्त आणि शोधावर केंद्रित ठेवा.", "Fendly ખોવાયેલી વસ્તુઓ, પાળતુ પ્રાણીઓ અને પ્રિયજનોને ફરી મેળવવામાં મદદ કરે છે. રિપોર્ટ સચોટ, આદરપૂર્ણ અને શોધ પર કેન્દ્રિત રાખો.", "Fendly হারানো জিনিস, পোষ্য ও প্রিয়জনকে খুঁজে পেতে সাহায্য করে। রিপোর্ট সঠিক, সম্মানজনক ও উদ্ধারের লক্ষ্যে রাখুন।", "Fendly தொலைந்த பொருட்கள், செல்லப்பிராணிகள் மற்றும் அன்புக்குரியவர்களை மீண்டும் கண்டுபிடிக்க உதவுகிறது. அறிக்கைகளைத் துல்லியமாகவும் மரியாதையாகவும் மீட்பில் கவனம் செலுத்தியும் வைத்திருங்கள்.", "Fendly పోయిన వస్తువులు, పెంపుడు జంతువులు మరియు ఆత్మీయులను తిరిగి కలపడంలో సహాయపడుతుంది. నివేదికలు ఖచ్చితంగా, గౌరవంగా, తిరిగి పొందడంపై దృష్టితో ఉండాలి.", "Fendly ಕಳೆದುಹೋದ ವಸ್ತುಗಳು, ಸಾಕುಪ್ರಾಣಿಗಳು ಮತ್ತು ಪ್ರೀತಿಪಾತ್ರರನ್ನು ಮತ್ತೆ ಪತ್ತೆಹಚ್ಚಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ. ವರದಿಗಳು ನಿಖರವಾಗಿ, ಗೌರವಯುತವಾಗಿ ಮತ್ತು ಪತ್ತೆಹಚ್ಚುವಿಕೆಗೆ ಸಂಬಂಧಿಸಿದಂತೆ ಇರಲಿ.", "Fendly നഷ്ടപ്പെട്ട വസ്തുക്കളെയും വളർത്തുമൃഗങ്ങളെയും പ്രിയപ്പെട്ടവരെയും വീണ്ടും കണ്ടെത്താൻ സഹായിക്കുന്നു. റിപ്പോർട്ടുകൾ കൃത്യവും മാന്യവും വീണ്ടെടുക്കലിൽ ശ്രദ്ധ കേന്ദ്രീകരിച്ചതുമായിരിക്കണം."),
            arrayOf("Allowed reports", "अनुमत रिपोर्टें", "मान्य अहवाल", "માન્ય રિપોર્ટ", "অনুমোদিত রিপোর্ট", "அனுமதிக்கப்பட்ட அறிக்கைகள்", "అనుమతించబడిన నివేదికలు", "ಅನುಮತಿಸಲಾದ ವರದಿಗಳು", "അനുവദനീയമായ റിപ്പോർട്ടുകൾ"),
            arrayOf("Submit truthful lost-and-found information that you are authorized to provide to Fendly.", "खोई या मिली वस्तु की वही सही जानकारी दें जिसे Fendly को देने का आपको अधिकार है।", "Fendly ला देण्याचा अधिकार असलेलीच हरवलेल्या किंवा सापडलेल्या वस्तूंची खरी माहिती द्या.", "Fendlyને આપવા માટે અધિકૃત હોવ તેવી જ ખોવાયેલી કે મળેલી વસ્તુની સાચી માહિતી આપો.", "Fendly-কে দেওয়ার অনুমতি আছে এমন সত্যিকারের হারানো-পাওয়া তথ্য দিন।", "Fendly-க்கு வழங்க உங்களுக்கு அனுமதியுள்ள உண்மையான தொலைந்த-கிடைத்த தகவலைச் சமர்ப்பிக்கவும்.", "Fendlyకి అందించడానికి మీకు అధికారం ఉన్న నిజమైన పోయిన/దొరికిన సమాచారాన్ని సమర్పించండి.", "Fendlyಗೆ ನೀಡಲು ನಿಮಗೆ ಅಧಿಕಾರವಿರುವ ನಿಜವಾದ ಕಳೆದುಹೋದ/ಸಿಕ್ಕಿದ ಮಾಹಿತಿಯನ್ನು ಸಲ್ಲಿಸಿ.", "Fendly-യ്ക്ക് നൽകാൻ നിങ്ങൾക്ക് അനുമതിയുള്ള യഥാർത്ഥ നഷ്ടപ്പെട്ട/ലഭിച്ച വിവരങ്ങൾ സമർപ്പിക്കുക."),
            arrayOf("Use photos and descriptions that help identify or recover the item, pet, or person.", "ऐसी तस्वीरें और विवरण इस्तेमाल करें जो वस्तु, पालतू जानवर या व्यक्ति की पहचान या खोज में मदद करें।", "वस्तू, पाळीव प्राणी किंवा व्यक्ती ओळखण्यास किंवा शोधण्यास मदत करणारे फोटो आणि वर्णन वापरा.", "વસ્તુ, પાળતુ પ્રાણી અથવા વ્યક્તિને ઓળખવા કે શોધવામાં મદદ કરે તેવા ફોટા અને વર્ણનો વાપરો.", "জিনিস, পোষ্য বা ব্যক্তিকে শনাক্ত বা খুঁজে পেতে সহায়ক ছবি ও বিবরণ ব্যবহার করুন।", "பொருள், செல்லப்பிராணி அல்லது நபரை அடையாளம் காண அல்லது மீட்க உதவும் படங்களையும் விளக்கங்களையும் பயன்படுத்தவும்.", "వస్తువు, పెంపుడు జంతువు లేదా వ్యక్తిని గుర్తించడానికి లేదా తిరిగి పొందడానికి సహాయపడే ఫోటోలు, వివరణలు వాడండి.", "ವಸ್ತು, ಸಾಕುಪ್ರಾಣಿ ಅಥವಾ ವ್ಯಕ್ತಿಯನ್ನು ಗುರುತಿಸಲು ಅಥವಾ ಪತ್ತೆಹಚ್ಚಲು ಸಹಾಯವಾಗುವ ಚಿತ್ರಗಳು ಮತ್ತು ವಿವರಣೆಗಳನ್ನು ಬಳಸಿ.", "വസ്തുവിനെയോ വളർത്തുമൃഗത്തെയോ വ്യക്തിയെയോ തിരിച്ചറിയാനും കണ്ടെത്താനും സഹായിക്കുന്ന ചിത്രങ്ങളും വിവരണങ്ങളും ഉപയോഗിക്കുക."),
            arrayOf("Share only the contact and location details needed for recovery. Report details are private to you and authorized Fendly administrators.", "खोज के लिए आवश्यक संपर्क और स्थान की जानकारी ही दें। रिपोर्ट की जानकारी केवल आपको और अधिकृत Fendly प्रशासकों को दिखती है।", "शोधासाठी आवश्यक संपर्क आणि ठिकाणाची माहितीच द्या. अहवालाची माहिती फक्त तुम्हाला आणि अधिकृत Fendly प्रशासकांना दिसते.", "શોધ માટે જરૂરી સંપર્ક અને સ્થાનની વિગતો જ આપો. રિપોર્ટની વિગતો ફક્ત તમને અને અધિકૃત Fendly સંચાલકોને દેખાય છે.", "উদ্ধারের জন্য প্রয়োজনীয় যোগাযোগ ও অবস্থানের তথ্যই দিন। রিপোর্টের তথ্য শুধু আপনি ও অনুমোদিত Fendly প্রশাসকরা দেখতে পারেন।", "மீட்புக்குத் தேவையான தொடர்பு மற்றும் இட விவரங்களை மட்டும் பகிரவும். அறிக்கை விவரங்கள் உங்களுக்கும் அங்கீகரிக்கப்பட்ட Fendly நிர்வாகிகளுக்கும் மட்டுமே தெரியும்.", "తిరిగి పొందడానికి అవసరమైన సంప్రదింపు, స్థల వివరాలనే పంచుకోండి. నివేదిక వివరాలు మీకు, అధీకృత Fendly నిర్వాహకులకు మాత్రమే కనిపిస్తాయి.", "ಪತ್ತೆಹಚ್ಚಲು ಅಗತ್ಯವಿರುವ ಸಂಪರ್ಕ ಮತ್ತು ಸ್ಥಳದ ವಿವರಗಳನ್ನು ಮಾತ್ರ ಹಂಚಿಕೊಳ್ಳಿ. ವರದಿ ವಿವರಗಳು ನಿಮಗೆ ಮತ್ತು ಅಧಿಕೃತ Fendly ನಿರ್ವಾಹಕರಿಗೆ ಮಾತ್ರ ಗೋಚರಿಸುತ್ತವೆ.", "വീണ്ടെടുക്കലിന് ആവശ്യമായ ബന്ധപ്പെടൽ, സ്ഥല വിവരങ്ങൾ മാത്രം പങ്കിടുക. റിപ്പോർട്ട് വിവരങ്ങൾ നിങ്ങൾക്കും അംഗീകൃത Fendly അഡ്മിനുകൾക്കും മാത്രമേ കാണാനാകൂ."),
            arrayOf("Pet adoption listings", "पालतू जानवर गोद लेने की सूचियाँ", "पाळीव प्राणी दत्तक सूची", "પાળતુ પ્રાણી દત્તક યાદીઓ", "পোষ্য দত্তক তালিকা", "செல்லப்பிராணி தத்தெடுப்பு பட்டியல்கள்", "పెంపుడు జంతువుల దత్తత జాబితాలు", "ಸಾಕುಪ್ರಾಣಿ ದತ್ತು ಪಟ್ಟಿಗಳು", "വളർത്തുമൃഗ ദത്തെടുക്കൽ പട്ടികകൾ"),
            arrayOf("Adoption listings and photos are public. Post only truthful information and photos you may share; do not include private contact details. Application details go to the lister for review. If you opt in to social posting, the public listing and first photo may also appear on Fendly's official Facebook and Instagram pages.", "गोद लेने की सूचियाँ और तस्वीरें सार्वजनिक होती हैं। केवल सही जानकारी और साझा करने योग्य तस्वीरें पोस्ट करें; निजी संपर्क विवरण न दें। आवेदन की जानकारी समीक्षा के लिए सूची बनाने वाले को भेजी जाती है। सोशल पोस्टिंग चुनने पर सार्वजनिक सूची और पहली तस्वीर Fendly के आधिकारिक Facebook और Instagram पेज पर भी दिख सकती है।", "दत्तक सूची आणि फोटो सार्वजनिक असतात. फक्त खरी माहिती आणि शेअर करण्यास परवानगी असलेले फोटो पोस्ट करा; खाजगी संपर्क तपशील देऊ नका. अर्जाचे तपशील तपासणीसाठी सूचीदाराकडे जातात. सोशल पोस्टिंग निवडल्यास सार्वजनिक सूची आणि पहिला फोटो Fendly च्या अधिकृत Facebook आणि Instagram पेजवरही दिसू शकतो.", "દત્તક યાદીઓ અને ફોટા જાહેર હોય છે. ફક્ત સાચી અને શેર કરવાની મંજૂરી હોય તેવી માહિતી/ફોટા મૂકો; ખાનગી સંપર્ક વિગતો ન આપો. અરજીની વિગતો સમીક્ષા માટે યાદી બનાવનારને મોકલાય છે. સોશિયલ પોસ્ટિંગ પસંદ કરો તો જાહેર યાદી અને પ્રથમ ફોટો Fendlyના સત્તાવાર Facebook અને Instagram પેજ પર પણ દેખાઈ શકે છે.", "দত্তক তালিকা ও ছবি সর্বজনীন। শুধু সত্য তথ্য ও শেয়ার করার অনুমতি আছে এমন ছবি দিন; ব্যক্তিগত যোগাযোগের তথ্য দেবেন না। পর্যালোচনার জন্য আবেদনের তথ্য তালিকাকারীর কাছে যায়। সামাজিক মাধ্যমে প্রকাশ বেছে নিলে তালিকা ও প্রথম ছবি Fendly-র অফিসিয়াল Facebook ও Instagram পেজেও দেখা যেতে পারে।", "தத்தெடுப்பு பட்டியல்களும் படங்களும் பொதுவானவை. உண்மையான தகவல்களையும் பகிர அனுமதியுள்ள படங்களையும் மட்டும் இடவும்; தனிப்பட்ட தொடர்பு விவரங்களைச் சேர்க்க வேண்டாம். விண்ணப்ப விவரங்கள் மதிப்பாய்வுக்காக பட்டியலிட்டவருக்கு அனுப்பப்படும். சமூக வலைதளப் பகிர்வைத் தேர்ந்தெடுத்தால், பட்டியலும் முதல் படமும் Fendly-யின் அதிகாரப்பூர்வ Facebook மற்றும் Instagram பக்கங்களில் தோன்றலாம்.", "దత్తత జాబితాలు, ఫోటోలు బహిరంగంగా ఉంటాయి. నిజమైన సమాచారం, పంచుకోవడానికి అనుమతించిన ఫోటోలనే పోస్ట్ చేయండి; వ్యక్తిగత సంప్రదింపు వివరాలు చేర్చవద్దు. దరఖాస్తు వివరాలు సమీక్ష కోసం జాబితా చేసిన వారికి వెళ్తాయి. సోషల్ పోస్టింగ్ ఎంచుకుంటే జాబితా, మొదటి ఫోటో Fendly అధికారిక Facebook, Instagram పేజీల్లో కనిపించవచ్చు.", "ದತ್ತು ಪಟ್ಟಿಗಳು ಮತ್ತು ಚಿತ್ರಗಳು ಸಾರ್ವಜನಿಕವಾಗಿರುತ್ತವೆ. ನಿಜವಾದ ಮಾಹಿತಿ ಮತ್ತು ಹಂಚಿಕೊಳ್ಳಲು ಅನುಮತಿಯಿರುವ ಚಿತ್ರಗಳನ್ನು ಮಾತ್ರ ಪೋಸ್ಟ್ ಮಾಡಿ; ಖಾಸಗಿ ಸಂಪರ್ಕ ವಿವರಗಳನ್ನು ಸೇರಿಸಬೇಡಿ. ಪರಿಶೀಲನೆಗಾಗಿ ಅರ್ಜಿ ವಿವರಗಳು ಪಟ್ಟಿ ಮಾಡಿದವರಿಗೆ ಕಳುಹಿಸಲಾಗುತ್ತದೆ. ಸಾಮಾಜಿಕ ಪೋಸ್ಟ್ ಆಯ್ಕೆ ಮಾಡಿದರೆ, ಸಾರ್ವಜನಿಕ ಪಟ್ಟಿ ಮತ್ತು ಮೊದಲ ಚಿತ್ರ Fendly ಅಧಿಕೃತ Facebook ಮತ್ತು Instagram ಪುಟಗಳಲ್ಲಿ ಕಾಣಿಸಬಹುದು.", "ദത്തെടുക്കൽ പട്ടികകളും ചിത്രങ്ങളും പൊതുവായവയാണ്. സത്യമായ വിവരങ്ങളും പങ്കിടാൻ അനുമതിയുള്ള ചിത്രങ്ങളും മാത്രം പോസ്റ്റ് ചെയ്യുക; സ്വകാര്യ ബന്ധപ്പെടൽ വിവരങ്ങൾ ചേർക്കരുത്. അപേക്ഷാ വിവരങ്ങൾ അവലോകനത്തിനായി പട്ടികപ്പെടുത്തിയ വ്യക്തിക്ക് കൈമാറും. സോഷ്യൽ പോസ്റ്റ് തിരഞ്ഞെടുക്കുകയാണെങ്കിൽ പൊതുപട്ടികയും ആദ്യ ചിത്രവും Fendly-യുടെ ഔദ്യോഗിക Facebook, Instagram പേജുകളിൽ പ്രത്യക്ഷപ്പെടാം."),
            arrayOf("Not allowed", "अनुमति नहीं है", "निषिद्ध", "પ્રતિબંધિત", "নিষিদ্ধ", "அனுமதிக்கப்படாதவை", "అనుమతించబడనివి", "ಅನುಮತಿಸದವು", "അനുവദനീയമല്ലാത്തത്"),
            arrayOf("Threats, harassment, hate, bullying, sexual exploitation, or graphic content.", "धमकी, उत्पीड़न, नफ़रत, डराना-धमकाना, यौन शोषण या आपत्तिजनक हिंसक सामग्री।", "धमक्या, छळ, द्वेष, धमकावणे, लैंगिक शोषण किंवा हिंसक/अश्लील सामग्री.", "ધમકી, હેરાનગતિ, નફરત, ધાકધમકી, જાતીય શોષણ અથવા હિંસક/ઘૃણાસ્પદ સામગ્રી.", "হুমকি, হয়রানি, বিদ্বেষ, বুলিং, যৌন শোষণ বা গ্রাফিক বিষয়বস্তু।", "அச்சுறுத்தல், துன்புறுத்தல், வெறுப்பு, கொடுமைப்படுத்தல், பாலியல் சுரண்டல் அல்லது வெளிப்படையான வன்முறை உள்ளடக்கம்.", "బెదిరింపులు, వేధింపులు, ద్వేషం, బెదిరించి ఇబ్బంది పెట్టడం, లైంగిక దోపిడీ లేదా గ్రాఫిక్ కంటెంట్.", "ಬೆದರಿಕೆ, ಕಿರುಕುಳ, ದ್ವೇಷ, ಹಿಂಸೆ, ಲೈಂಗಿಕ ಶೋಷಣೆ ಅಥವಾ ಅತಿಯಾದ ಹಿಂಸಾತ್ಮಕ ವಿಷಯ.", "ഭീഷണി, ഉപദ്രവം, വിദ്വേഷം, ബുള്ളിയിംഗ്, ലൈംഗിക ചൂഷണം അല്ലെങ്കിൽ ഗ്രാഫിക് ഉള്ളടക്കം."),
            arrayOf("Spam, scams, impersonation, knowingly false reports, or content promoting illegal activity.", "स्पैम, धोखाधड़ी, किसी और का रूप धारण करना, जानबूझकर झूठी रिपोर्ट या गैरकानूनी गतिविधि को बढ़ावा देने वाली सामग्री।", "स्पॅम, फसवणूक, दुसऱ्याचे रूप घेणे, जाणीवपूर्वक खोटे अहवाल किंवा बेकायदेशीर कृतीला प्रोत्साहन देणारी सामग्री.", "સ્પામ, છેતરપિંડી, ખોટી ઓળખ, જાણી જોઈને ખોટા રિપોર્ટ અથવા ગેરકાયદે પ્રવૃત્તિને પ્રોત્સાહન આપતી સામગ્રી.", "স্প্যাম, প্রতারণা, ছদ্মবেশ, জেনেশুনে মিথ্যা রিপোর্ট বা বেআইনি কাজকে উৎসাহিত করে এমন বিষয়বস্তু।", "ஸ்பாம், மோசடி, ஆள்மாறாட்டம், தெரிந்தே அளிக்கும் பொய்யான அறிக்கைகள் அல்லது சட்டவிரோத செயல்களை ஊக்குவிக்கும் உள்ளடக்கம்.", "స్పామ్, మోసాలు, వేరొకరిగా నటించడం, తెలిసి తప్పుడు నివేదికలు లేదా చట్టవిరుద్ధ కార్యకలాపాలను ప్రోత్సహించే కంటెంట్.", "ಸ್ಪ್ಯಾಮ್, ವಂಚನೆ, ಸೋಗು ಹಾಕುವುದು, ತಿಳಿದೂ ಸುಳ್ಳು ವರದಿಗಳು ಅಥವಾ ಕಾನೂನುಬಾಹಿರ ಚಟುವಟಿಕೆಯನ್ನು ಉತ್ತೇಜಿಸುವ ವಿಷಯ.", "സ്പാം, തട്ടിപ്പ്, ആൾമാറാട്ടം, അറിഞ്ഞുകൊണ്ടുള്ള തെറ്റായ റിപ്പോർട്ടുകൾ അല്ലെങ്കിൽ നിയമവിരുദ്ധ പ്രവർത്തനം പ്രോത്സാഹിപ്പിക്കുന്ന ഉള്ളടക്കം."),
            arrayOf("Other people's passwords, financial details, private contact information, or sensitive personal information.", "दूसरों के पासवर्ड, वित्तीय जानकारी, निजी संपर्क विवरण या संवेदनशील व्यक्तिगत जानकारी।", "इतरांचे पासवर्ड, आर्थिक माहिती, खाजगी संपर्क तपशील किंवा संवेदनशील वैयक्तिक माहिती.", "બીજાના પાસવર્ડ, નાણાકીય વિગતો, ખાનગી સંપર્ક માહિતી અથવા સંવેદનશીલ વ્યક્તિગત માહિતી.", "অন্যের পাসওয়ার্ড, আর্থিক তথ্য, ব্যক্তিগত যোগাযোগের তথ্য বা সংবেদনশীল ব্যক্তিগত তথ্য।", "பிறரின் கடவுச்சொற்கள், நிதி விவரங்கள், தனிப்பட்ட தொடர்புத் தகவல் அல்லது முக்கியமான தனிப்பட்ட தகவல்.", "ఇతరుల పాస్‌వర్డ్‌లు, ఆర్థిక వివరాలు, ప్రైవేట్ సంప్రదింపు సమాచారం లేదా సున్నితమైన వ్యక్తిగత సమాచారం.", "ಇತರರ ಪಾಸ್‌ವರ್ಡ್‌ಗಳು, ಹಣಕಾಸಿನ ವಿವರಗಳು, ಖಾಸಗಿ ಸಂಪರ್ಕ ಮಾಹಿತಿ ಅಥವಾ ಸೂಕ್ಷ್ಮ ವೈಯಕ್ತಿಕ ಮಾಹಿತಿ.", "മറ്റുള്ളവരുടെ പാസ്‌വേഡുകൾ, സാമ്പത്തിക വിവരങ്ങൾ, സ്വകാര്യ ബന്ധപ്പെടൽ വിവരങ്ങൾ അല്ലെങ്കിൽ സംവേദനക്ഷമമായ വ്യക്തിഗത വിവരങ്ങൾ."),
            arrayOf("Content you do not have permission to post, or content unrelated to Fendly's lost-and-found purpose.", "ऐसी सामग्री जिसे पोस्ट करने की अनुमति आपके पास नहीं है, या जो Fendly के खोया-पाया उद्देश्य से संबंधित नहीं है।", "पोस्ट करण्याची परवानगी नसलेली किंवा Fendly च्या हरवले-सापडले उद्देशाशी संबंधित नसलेली सामग्री.", "જે સામગ્રી પોસ્ટ કરવાની પરવાનગી ન હોય અથવા Fendlyના ખોવાયેલ-મળેલ હેતુ સાથે સંબંધિત ન હોય.", "পোস্ট করার অনুমতি নেই এমন বিষয়বস্তু বা Fendly-র হারানো-পাওয়ার উদ্দেশ্যের সঙ্গে সম্পর্কহীন বিষয়বস্তু।", "இட அனுமதியில்லாத அல்லது Fendly-யின் தொலைந்த-கிடைத்த நோக்கத்துடன் தொடர்பில்லாத உள்ளடக்கம்.", "పోస్ట్ చేయడానికి అనుమతి లేని లేదా Fendly పోయిన/దొరికిన లక్ష్యానికి సంబంధం లేని కంటెంట్.", "ಪೋಸ್ಟ್ ಮಾಡಲು ಅನುಮತಿಯಿಲ್ಲದ ಅಥವಾ Fendly ಕಳೆದುಹೋದ/ಸಿಕ್ಕಿದ ಉದ್ದೇಶಕ್ಕೆ ಸಂಬಂಧಿಸದ ವಿಷಯ.", "പോസ്റ്റ് ചെയ്യാൻ അനുമതിയില്ലാത്തതോ Fendly-യുടെ നഷ്ടപ്പെട്ട/ലഭിച്ച ഉദ്ദേശ്യവുമായി ബന്ധമില്ലാത്തതോ ആയ ഉള്ളടക്കം."),
            arrayOf("Reporting and enforcement", "रिपोर्ट की समीक्षा और कार्रवाई", "अहवाल तपासणी आणि अंमलबजावणी", "રિપોર્ટની સમીક્ષા અને અમલ", "রিপোর্ট পর্যালোচনা ও ব্যবস্থা", "அறிக்கை மதிப்பாய்வு மற்றும் நடவடிக்கை", "నివేదిక సమీక్ష మరియు అమలు", "ವರದಿ ಪರಿಶೀಲನೆ ಮತ್ತು ಜಾರಿ", "റിപ്പോർട്ട് അവലോകനവും നടപടിയും"),
            arrayOf("Lost-and-found reports are visible to their owner and authorized Fendly administrators, not other users. Administrators review unverified reports and verify evidence before confirming a match. They may remove fake or abusive reports. Owners may delete their own reports. Reports are not automatically posted to social media; reunion stories are shared outside Fendly only after administrator review and the owner's consent.", "खोई-मिली रिपोर्ट केवल उसके मालिक और अधिकृत Fendly प्रशासकों को दिखती है, अन्य उपयोगकर्ताओं को नहीं। प्रशासक अपुष्ट रिपोर्टों की समीक्षा और मिलान की पुष्टि से पहले सबूत जाँचते हैं। वे नकली या अपमानजनक रिपोर्ट हटा सकते हैं। मालिक अपनी रिपोर्ट हटा सकते हैं। रिपोर्ट सोशल मीडिया पर अपने-आप पोस्ट नहीं होतीं; पुनर्मिलन की कहानियाँ प्रशासक की समीक्षा और मालिक की सहमति के बाद ही साझा होती हैं।", "हरवलेल्या-सापडलेल्या वस्तूंचे अहवाल फक्त मालक आणि अधिकृत Fendly प्रशासकांना दिसतात; इतर वापरकर्त्यांना नाही. प्रशासक अपुष्ट अहवाल तपासतात आणि जुळणी निश्चित करण्यापूर्वी पुरावे पडताळतात. बनावट किंवा अपमानास्पद अहवाल काढले जाऊ शकतात. मालक स्वतःचे अहवाल हटवू शकतात. अहवाल सोशल मीडियावर आपोआप पोस्ट होत नाहीत; पुनर्भेटीच्या कथा प्रशासकीय तपासणी आणि मालकाच्या संमतीनंतरच शेअर होतात.", "ખોવાયેલ-મળેલ રિપોર્ટ ફક્ત તેના માલિક અને અધિકૃત Fendly સંચાલકો જોઈ શકે છે, અન્ય વપરાશકર્તાઓ નહીં. સંચાલકો અચકાસેલા રિપોર્ટની સમીક્ષા કરે છે અને મેળની પુષ્ટિ પહેલાં પુરાવા ચકાસે છે. નકલી અથવા અપમાનજનક રિપોર્ટ દૂર કરી શકે છે. માલિક પોતાના રિપોર્ટ કાઢી શકે છે. રિપોર્ટ સોશિયલ મીડિયા પર આપમેળે મૂકાતા નથી; ફરી મળવાની વાર્તા સંચાલકની સમીક્ષા અને માલિકની સંમતિ પછી જ શેર થાય છે.", "হারানো-পাওয়ার রিপোর্ট শুধু মালিক ও অনুমোদিত Fendly প্রশাসকরা দেখতে পারেন, অন্য ব্যবহারকারীরা নয়। প্রশাসকেরা যাচাইহীন রিপোর্ট পর্যালোচনা করেন এবং মিল নিশ্চিত করার আগে প্রমাণ যাচাই করেন। ভুয়া বা আপত্তিকর রিপোর্ট সরানো হতে পারে। মালিক নিজের রিপোর্ট মুছতে পারেন। রিপোর্ট স্বয়ংক্রিয়ভাবে সামাজিক মাধ্যমে প্রকাশিত হয় না; প্রশাসকের পর্যালোচনা ও মালিকের সম্মতির পরই পুনর্মিলনের গল্প বাইরে শেয়ার হয়।", "தொலைந்த-கிடைத்த அறிக்கைகளை உரிமையாளரும் அங்கீகரிக்கப்பட்ட Fendly நிர்வாகிகளும் மட்டுமே காண முடியும்; பிற பயனர்கள் காண முடியாது. நிர்வாகிகள் சரிபார்க்கப்படாத அறிக்கைகளை மதிப்பாய்வு செய்து, பொருத்தத்தை உறுதிப்படுத்தும் முன் ஆதாரங்களைச் சரிபார்ப்பார்கள். போலியான அல்லது தவறான அறிக்கைகளை நீக்கலாம். உரிமையாளர்கள் தங்கள் அறிக்கைகளை நீக்கலாம். அறிக்கைகள் தானாக சமூக வலைதளங்களில் இடப்படாது; நிர்வாக மதிப்பாய்வு மற்றும் உரிமையாளரின் ஒப்புதலுக்குப் பிறகே மீண்டும் இணைந்த கதைகள் பகிரப்படும்.", "పోయిన/దొరికిన నివేదికలు వాటి యజమాని, అధీకృత Fendly నిర్వాహకులకు మాత్రమే కనిపిస్తాయి; ఇతర వినియోగదారులకు కాదు. నిర్వాహకులు ధృవీకరించని నివేదికలను సమీక్షించి, సరిపోలికను నిర్ధారించే ముందు ఆధారాలను తనిఖీ చేస్తారు. నకిలీ లేదా దుర్వినియోగ నివేదికలను తొలగించవచ్చు. యజమానులు తమ నివేదికలను తొలగించవచ్చు. నివేదికలు సోషల్ మీడియాలో ఆటోమేటిక్‌గా పోస్ట్ కావు; నిర్వాహకుల సమీక్ష, యజమాని సమ్మతి తర్వాతే తిరిగి కలిసిన కథలు పంచబడతాయి.", "ಕಳೆದುಹೋದ/ಸಿಕ್ಕಿದ ವರದಿಗಳನ್ನು ಅದರ ಮಾಲೀಕರು ಮತ್ತು ಅಧಿಕೃತ Fendly ನಿರ್ವಾಹಕರು ಮಾತ್ರ ನೋಡಬಹುದು; ಇತರ ಬಳಕೆದಾರರು ನೋಡಲಾಗುವುದಿಲ್ಲ. ನಿರ್ವಾಹಕರು ಪರಿಶೀಲಿಸದ ವರದಿಗಳನ್ನು ಪರಿಶೀಲಿಸಿ, ಹೊಂದಾಣಿಕೆ ದೃಢೀಕರಿಸುವ ಮೊದಲು ಸಾಕ್ಷ್ಯವನ್ನು ದೃಢಪಡಿಸುತ್ತಾರೆ. ನಕಲಿ ಅಥವಾ ದುರುಪಯೋಗದ ವರದಿಗಳನ್ನು ತೆಗೆದುಹಾಕಬಹುದು. ಮಾಲೀಕರು ತಮ್ಮ ವರದಿಗಳನ್ನು ಅಳಿಸಬಹುದು. ವರದಿಗಳು ಸಾಮಾಜಿಕ ಮಾಧ್ಯಮದಲ್ಲಿ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಪ್ರಕಟವಾಗುವುದಿಲ್ಲ; ನಿರ್ವಾಹಕರ ಪರಿಶೀಲನೆ ಮತ್ತು ಮಾಲೀಕರ ಒಪ್ಪಿಗೆಯ ನಂತರವೇ ಪುನರ್ಮಿಲನದ ಕಥೆಗಳನ್ನು ಹಂಚಲಾಗುತ್ತದೆ.", "നഷ്ടപ്പെട്ട/ലഭിച്ച റിപ്പോർട്ടുകൾ ഉടമയ്ക്കും അംഗീകൃത Fendly അഡ്മിനുകൾക്കും മാത്രമേ കാണാനാകൂ; മറ്റ് ഉപയോക്താക്കൾക്ക് കാണാനാകില്ല. അഡ്മിനുകൾ സ്ഥിരീകരിക്കാത്ത റിപ്പോർട്ടുകൾ അവലോകനം ചെയ്യുകയും പൊരുത്തം ഉറപ്പിക്കുന്നതിന് മുമ്പ് തെളിവുകൾ പരിശോധിക്കുകയും ചെയ്യും. വ്യാജമോ ദുരുപയോഗപരമോ ആയ റിപ്പോർട്ടുകൾ നീക്കം ചെയ്യാം. ഉടമകൾക്ക് സ്വന്തം റിപ്പോർട്ടുകൾ ഇല്ലാതാക്കാം. റിപ്പോർട്ടുകൾ സോഷ്യൽ മീഡിയയിൽ സ്വമേധയാ പ്രസിദ്ധീകരിക്കില്ല; അഡ്മിൻ അവലോകനത്തിനും ഉടമയുടെ സമ്മതത്തിനും ശേഷമേ വീണ്ടും ഒന്നിച്ച കഥകൾ പങ്കിടൂ."),
            arrayOf("Share a generated poster or alert card outside Fendly only if you intend to disclose the information shown. After sharing, its audience and copies are controlled by the receiving app or service.", "Fendly के बाहर बनाया गया पोस्टर या अलर्ट कार्ड तभी साझा करें जब उसमें दिखाई गई जानकारी बताना चाहते हों। साझा करने के बाद उसे कौन देखेगा और उसकी प्रतियाँ कहाँ रहेंगी, यह दूसरी ऐप या सेवा नियंत्रित करती है।", "तयार केलेले पोस्टर किंवा सूचना कार्ड त्यावरील माहिती उघड करण्याची तयारी असल्यासच Fendly बाहेर शेअर करा. शेअर केल्यानंतर ते कोण पाहू शकते आणि त्याच्या प्रती कुठे राहतात हे संबंधित अॅप किंवा सेवा ठरवते.", "તૈયાર કરેલું પોસ્ટર અથવા ચેતવણી કાર્ડ તેમાંની માહિતી જાહેર કરવાની ઇચ્છા હોય ત્યારે જ Fendlyની બહાર શેર કરો. શેર થયા પછી તેને કોણ જોઈ શકે અને તેની નકલો ક્યાં રહે તે પ્રાપ્ત કરનાર એપ અથવા સેવા નક્કી કરે છે.", "তৈরি করা পোস্টার বা সতর্কতা কার্ডে থাকা তথ্য প্রকাশ করতে চাইলে তবেই Fendly-র বাইরে শেয়ার করুন। শেয়ারের পরে কারা দেখবে ও কপি কোথায় থাকবে তা গ্রহণকারী অ্যাপ বা পরিষেবা নিয়ন্ত্রণ করে।", "உருவாக்கப்பட்ட சுவரொட்டி அல்லது எச்சரிக்கை அட்டையில் உள்ள தகவலை வெளிப்படுத்த விரும்பினால் மட்டுமே Fendly-க்கு வெளியே பகிரவும். பகிர்ந்த பிறகு, அதை யார் காணலாம் மற்றும் நகல்கள் எங்கு இருக்கும் என்பதைப் பெறும் செயலி அல்லது சேவை கட்டுப்படுத்தும்.", "తయారైన పోస్టర్ లేదా హెచ్చరిక కార్డులోని సమాచారాన్ని బయటపెట్టాలనుకుంటే మాత్రమే Fendly వెలుపల పంచుకోండి. పంచుకున్న తర్వాత దాన్ని ఎవరు చూడగలరు, కాపీలు ఎక్కడ ఉంటాయి అనేది స్వీకరించే యాప్ లేదా సేవ నియంత్రిస్తుంది.", "ರಚಿಸಿದ ಪೋಸ್ಟರ್ ಅಥವಾ ಎಚ್ಚರಿಕೆ ಕಾರ್ಡ್‌ನಲ್ಲಿರುವ ಮಾಹಿತಿಯನ್ನು ಬಹಿರಂಗಪಡಿಸಲು ಉದ್ದೇಶಿಸಿದಾಗ ಮಾತ್ರ Fendly ಹೊರಗೆ ಹಂಚಿಕೊಳ್ಳಿ. ಹಂಚಿದ ನಂತರ ಅದನ್ನು ಯಾರು ನೋಡಬಹುದು ಮತ್ತು ಪ್ರತಿಗಳು ಎಲ್ಲಿ ಉಳಿಯುತ್ತವೆ ಎಂಬುದನ್ನು ಸ್ವೀಕರಿಸುವ ಆ್ಯಪ್ ಅಥವಾ ಸೇವೆ ನಿಯಂತ್ರಿಸುತ್ತದೆ.", "സൃഷ്ടിച്ച പോസ്റ്ററിലോ അലർട്ട് കാർഡിലോ ഉള്ള വിവരങ്ങൾ വെളിപ്പെടുത്താൻ ഉദ്ദേശിക്കുന്നുവെങ്കിൽ മാത്രം Fendly-യ്ക്ക് പുറത്തേക്ക് പങ്കിടുക. പങ്കിട്ടതിന് ശേഷം അത് ആർക്കൊക്കെ കാണാം, പകർപ്പുകൾ എവിടെ നിലനിൽക്കും എന്നിവ സ്വീകരിക്കുന്ന ആപ്പോ സേവനമോ നിയന്ത്രിക്കും."),
            arrayOf("Do not publish sensitive information about a missing person in a Fendly report. Contact local emergency services if someone may be in immediate danger.", "Fendly रिपोर्ट में लापता व्यक्ति की संवेदनशील जानकारी प्रकाशित न करें। किसी के तत्काल खतरे में होने पर स्थानीय आपातकालीन सेवाओं से संपर्क करें।", "बेपत्ता व्यक्तीची संवेदनशील माहिती Fendly अहवालात प्रकाशित करू नका. कोणाला तातडीचा धोका असल्यास स्थानिक आपत्कालीन सेवांशी संपर्क साधा.", "Fendly રિપોર્ટમાં ગુમ વ્યક્તિની સંવેદનશીલ માહિતી જાહેર ન કરો. કોઈને તાત્કાલિક જોખમ હોય તો સ્થાનિક કટોકટી સેવાઓનો સંપર્ક કરો.", "Fendly রিপোর্টে নিখোঁজ ব্যক্তির সংবেদনশীল তথ্য প্রকাশ করবেন না। কেউ তাৎক্ষণিক বিপদে থাকলে স্থানীয় জরুরি পরিষেবায় যোগাযোগ করুন।", "காணாமல் போனவரைப் பற்றிய முக்கியமான தகவலை Fendly அறிக்கையில் வெளியிட வேண்டாம். யாராவது உடனடி ஆபத்தில் இருந்தால் உள்ளூர் அவசர சேவைகளைத் தொடர்புகொள்ளவும்.", "కనిపించని వ్యక్తి గురించి సున్నితమైన సమాచారాన్ని Fendly నివేదికలో ప్రచురించవద్దు. ఎవరైనా తక్షణ ప్రమాదంలో ఉంటే స్థానిక అత్యవసర సేవలను సంప్రదించండి.", "ಕಾಣೆಯಾದ ವ್ಯಕ್ತಿಯ ಸೂಕ್ಷ್ಮ ಮಾಹಿತಿಯನ್ನು Fendly ವರದಿಯಲ್ಲಿ ಪ್ರಕಟಿಸಬೇಡಿ. ಯಾರಾದರೂ ತಕ್ಷಣದ ಅಪಾಯದಲ್ಲಿದ್ದರೆ ಸ್ಥಳೀಯ ತುರ್ತು ಸೇವೆಗಳನ್ನು ಸಂಪರ್ಕಿಸಿ.", "കാണാതായ വ്യക്തിയെക്കുറിച്ചുള്ള സംവേദനക്ഷമമായ വിവരങ്ങൾ Fendly റിപ്പോർട്ടിൽ പ്രസിദ്ധീകരിക്കരുത്. ആരെങ്കിലും അടിയന്തര അപകടത്തിലാണെങ്കിൽ പ്രാദേശിക അടിയന്തര സേവനങ്ങളെ ബന്ധപ്പെടുക."),
            arrayOf("For privacy and deletion information, see the Fendly Privacy Policy.", "गोपनीयता और हटाने की जानकारी के लिए Fendly गोपनीयता नीति देखें।", "गोपनीयता आणि हटवण्याच्या माहितीसाठी Fendly गोपनीयता धोरण पहा.", "ગોપનીયતા અને કાઢી નાખવાની માહિતી માટે Fendly ગોપનીયતા નીતિ જુઓ.", "গোপনীয়তা ও মুছে ফেলার তথ্যের জন্য Fendly গোপনীয়তা নীতি দেখুন।", "தனியுரிமை மற்றும் நீக்குதல் தகவலுக்கு Fendly தனியுரிமைக் கொள்கையைப் பார்க்கவும்.", "గోప్యత, తొలగింపు వివరాల కోసం Fendly గోప్యతా విధానాన్ని చూడండి.", "ಗೌಪ್ಯತೆ ಮತ್ತು ಅಳಿಸುವಿಕೆಯ ಮಾಹಿತಿಗಾಗಿ Fendly ಗೌಪ್ಯತಾ ನೀತಿಯನ್ನು ನೋಡಿ.", "സ്വകാര്യതയും നീക്കംചെയ്യലും സംബന്ധിച്ച വിവരങ്ങൾക്ക് Fendly സ്വകാര്യതാ നയം കാണുക.")
        )
        val language = getSavedLanguageIndex(context)
        fun text(index: Int): String = translations[index][language]
            .replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
        val colorScheme = if (darkMode) "dark" else "light"
        val textColor = if (darkMode) "#F1F1F1" else "#202124"
        val linkColor = if (darkMode) "#8AB4F8" else "#3978D4"

        return """
            <!doctype html>
            <html lang="${getSavedLanguage(context)}">
            <head>
              <meta charset="utf-8">
              <meta name="viewport" content="width=device-width, initial-scale=1">
              <style>
                :root { color-scheme: $colorScheme; font: 16px/1.6 sans-serif; }
                body { color: $textColor; margin: 0 auto; max-width: 760px; padding: 16px; }
                h1, h2 { line-height: 1.25; }
                h2 { margin-top: 1.5em; }
                a { color: $linkColor; }
              </style>
            </head>
            <body>
              <main>
                <h1>${text(0)}</h1>
                <p>${text(1)}</p>
                <h2>${text(2)}</h2>
                <ul><li>${text(3)}</li><li>${text(4)}</li><li>${text(5)}</li></ul>
                <h2>${text(6)}</h2>
                <p>${text(7)}</p>
                <h2>${text(8)}</h2>
